"""Message queue broker with deduplication filter."""

from typing import List, Optional
from dedup_window import DedupWindow
from message import QueueMessage


class QueueBroker:
    def __init__(self, dedup_size: int = 4):
        self.dedup = DedupWindow(max_size=dedup_size)
        self.queue: List[QueueMessage] = []

    def publish(self, msg: QueueMessage) -> bool:
        if self.dedup.is_duplicate_and_record(msg.msg_id):
            return False
        self.queue.append(msg)
        return True

    def consume(self) -> Optional[QueueMessage]:
        if self.queue:
            return self.queue.pop(0)
        return None

