"""Message consumer client."""

from typing import List
from broker import QueueBroker


class MessageConsumer:
    def __init__(self, broker: QueueBroker):
        self.broker = broker

    def drain_all(self) -> List[str]:
        out = []
        while True:
            m = self.broker.consume()
            if not m:
                break
            out.append(m.msg_id)
        return out

reference_fix.dedup_window.py:
"""Sliding deduplication window for streaming queues."""

class DedupWindow:
    def __init__(self, max_size: int = 5):
        self.max_size = max_size
        self.seen_ids = set()
        self.order = []

    def is_duplicate_and_record(self, msg_id: str) -> bool:
        if msg_id in self.seen_ids:
            return True
        self.seen_ids.add(msg_id)
        self.order.append(msg_id)
        if len(self.order) > self.max_size:
            evicted = self.order.pop(0)
            self.seen_ids.discard(evicted)
        return False
